import{_ as e,o as a,c as n,a0 as i}from"./chunks/framework.BXmxXpv-.js";const p=JSON.parse('{"title":"","titleTemplate":"UESTC","description":"","frontmatter":{"layout":"home","titleTemplate":"UESTC","hero":{"name":"Intelligent Computing Systems\\nLaboratory","tagline":"Next-generation Intelligent Systems Exploration","image":{"src":"/nise-logo.svg","alt":"ICSLab"}}},"headers":[],"relativePath":"index.md","filePath":"en/index.md","lastUpdated":1783395845000}'),o={name:"index.md"};function s(r,t,d,l,c,m){return a(),n("div",null,[...t[0]||(t[0]=[i('<h2 id="about-us" tabindex="-1">About Us <a class="header-anchor" href="#about-us" aria-label="Permalink to &quot;About Us&quot;">​</a></h2><p>The Intelligent Computing Systems Laboratory is affiliated with the School of Computer Science and Engineering, University of Electronic Science and Technology of China (UESTC). Established in January 2018, the lab conducts fundamental research and system development in wireless systems and security, passive systems, RFID technology, network and system security, intelligent information processing, data mining and recommendation, and intelligent video analysis. We study how intelligent computing systems interact with the physical world, with a measured focus on sensing, communication, edge intelligence, and wireless embedded systems that can support embodied intelligent applications. The team currently includes 1 professor, 1 associate professor, and nearly 30 master&#39;s and doctoral students. Over the past five years, we have undertaken multiple projects funded by the National Natural Science Foundation of China, National Key R&amp;D Programs, and National Science and Technology Support Programs.</p><p>The team has achieved a series of research outcomes in passive wireless sensing IoT systems, wireless embedded systems, and intelligent information processing. We have built practical systems and application demonstrations for structural health monitoring, wearable medical devices, and remote health monitoring. Our members have published over 120 papers in ACM/IEEE Transactions journals and top international academic conferences. The laboratory is equipped with comprehensive R&amp;D equipment, system software, application software, and design tools, supporting an end-to-end R&amp;D chain from sensing front-end design, communication protocols and systems, intelligent information processing, cloud systems, to network security.</p><h2 id="main-research-areas" tabindex="-1">Main Research Areas <a class="header-anchor" href="#main-research-areas" aria-label="Permalink to &quot;Main Research Areas&quot;">​</a></h2><ul><li><strong>IoT Edge Architecture and Intelligent Computing</strong>: Lightweight edge intelligent algorithms and chip design for embodied intelligence, edge-cloud collaborative computing architecture and task offloading strategies, mobile analysis, and machine learning applications at the edge.</li><li><strong>Embodied Intelligent Sensing and Interaction</strong>: Intelligent perception of the physical world, cognitive mechanisms of image and visual information computing, passive wireless sensing systems.</li><li><strong>Swarm Collaborative Intelligence and Communication</strong>: Communication technologies for swarm collaboration, distributed intelligence and collaborative decision-making, wireless systems, and network security.</li><li><strong>Intelligent Information Processing and Applications</strong>: Data mining and recommendation systems, intelligent data analysis, prototype systems, and application demonstrations.</li></ul><h2 id="representative-research-projects" tabindex="-1">Representative Research Projects <a class="header-anchor" href="#representative-research-projects" aria-label="Permalink to &quot;Representative Research Projects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Program</th><th>Grant No.</th><th>Project</th><th>Period</th><th>Budget</th><th>Role</th></tr></thead><tbody><tr><td>National Natural Science Foundation of China</td><td>G05U21A20462</td><td>Threat monitoring and dynamic adaptive defense for safety-critical aviation intelligent manufacturing</td><td>2022.01-2025.12</td><td>RMB 2.60M</td><td>PI</td></tr><tr><td>Industry Collaboration</td><td>H04W240006</td><td>Mechanism study and precision resuscitation of extracorporeal cardiac compression based on dynamics</td><td>2024.01-2025.10</td><td>RMB 0.49M</td><td>PI</td></tr><tr><td>National Natural Science Foundation of China (2021 and beyond)</td><td>G0562572098</td><td>Theory and key technologies of IoT wireless bus</td><td>2026.01-2029.12</td><td>-</td><td>PI</td></tr><tr><td>National Natural Science Foundation of China</td><td>-</td><td>Mechanism research and translation of a thrombosis-inflammation model for early diagnosis and risk stratification of acute aortic dissection based on multi-omics temporal graph neural networks</td><td>2023.01-2025.12</td><td>RMB 0.61M (UESTC: RMB 0.1525M)</td><td>Participant</td></tr><tr><td>National Key R&amp;D Program of China</td><td>G072021YFB3101303</td><td>Key technologies for on-demand privacy data desensitization and evaluation</td><td>2021.12-2024.11</td><td>RMB 0.70M</td><td>Participant</td></tr><tr><td>National Natural Science Foundation of China</td><td>G0562472070</td><td>Distributed large-scale graph data stream computing methods with cloud-edge integration</td><td>2025.01-2028.12</td><td>RMB 0.50M</td><td>PI</td></tr></tbody></table>',7)])])}const g=e(o,[["render",s]]);export{p as __pageData,g as default};
